class Solution {
    struct R { int rob, skip; };
    R dfs(TreeNode* node) {
        if (!node) return {0, 0};
        R l = dfs(node->left);
        R r = dfs(node->right);
        return { node->val + l.skip + r.skip,
                 max(l.rob, l.skip) + max(r.rob, r.skip) };
    }
public:
    int rob(TreeNode* root) {
        R p = dfs(root);
        return max(p.rob, p.skip);
    }
};
